const chap=(n,title,photo)=>`<div class="chap" data-k="bg"></div>${photo?`<div class="a" data-k="bg" style="left:0;top:0;width:1920px;height:1080px;background:url(${A}photos/${photo}.jpg) center/cover;opacity:.28"></div>`:''}<div class="a" data-k="text" style="left:160px;top:300px;font:900 300px Poppins;color:#FFE14D;line-height:1">${n}</div><div class="a" data-k="text" style="left:420px;top:390px;font:900 104px Poppins;color:#fff;line-height:1.1;width:1400px">${title}</div>`;
const clock=(cx,cy,r,h,m,arc=null)=>{ // arc=[fromMin,toMin] in minutes on the dial
  const ang=x=>x/60*2*Math.PI-Math.PI/2; const hh=(h%12+m/60)*5;
  const pt=(mm,rr)=>[cx+rr*Math.cos(ang(mm)),cy+rr*Math.sin(ang(mm))];
  let arcP='';if(arc){const [a,b]=arc;const [x1,y1]=pt(a,r*.82),[x2,y2]=pt(b,r*.82);arcP=`<path d="M${cx},${cy} L${x1},${y1} A${r*.82},${r*.82} 0 ${(b-a)>30?1:0} 1 ${x2},${y2} Z" fill="rgba(227,27,27,.28)"/>`;}
  const ticks=[...Array(12)].map((_,i)=>{const [x1,y1]=pt(i*5,r*.86),[x2,y2]=pt(i*5,r*.96);return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#151515" stroke-width="8"/>`}).join('');
  const [hx,hy]=pt(hh,r*.5),[mx,my]=pt(m,r*.75);
  return `<svg class="a" data-k="icon" style="left:${cx-r-10}px;top:${cy-r-10}px;overflow:visible" width="${2*r+20}" height="${2*r+20}" viewBox="${cx-r-10} ${cy-r-10} ${2*r+20} ${2*r+20}"><circle cx="${cx}" cy="${cy}" r="${r}" fill="#fff" stroke="#151515" stroke-width="14"/>${arcP}${ticks}<line x1="${cx}" y1="${cy}" x2="${hx}" y2="${hy}" stroke="#151515" stroke-width="16" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${mx}" y2="${my}" stroke="#151515" stroke-width="10" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="14" fill="#E31B1B"/></svg>`};
// a horizontal day bar: segs=[[label,from,to,color]], scale px per unit
const bar=(x,y,w,segs,u0,u1,h=110)=>{const s=w/(u1-u0);return `<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="${w}" height="${h}">${segs.map(([n,a,b,c])=>{const bw=(b-a)*s-6;const fs=Math.min(44,(bw-20)/(Math.max(n.length,1)*0.68));return `<rect x="${(a-u0)*s}" y="0" width="${bw}" height="${h}" rx="16" fill="${c}"/><text x="${(a-u0)*s+bw/2}" y="${h/2+fs*0.36}" text-anchor="middle" font-family="Poppins" font-weight="900" font-size="${fs}" fill="#fff">${n}</text>`}).join('')}</svg>`};
const sky=(sunX,sunY,col='#FFC83D',grade='#BFE3FF,#E9F6FF')=>`<div class="a" data-k="bg" style="inset:0;background:linear-gradient(180deg,${grade})"></div><div class="a" data-k="bg" style="left:0;right:0;top:820px;bottom:0;background:#6E8B5B"></div><svg class="a" data-k="bg" style="inset:0" width="1920" height="1080"><path d="M160,820 Q960,40 1760,820" fill="none" stroke="#ffffff" stroke-width="8" stroke-dasharray="20 18"/></svg><div class="a" data-k="bg" style="left:${sunX-70}px;top:${sunY-70}px;width:140px;height:140px;border-radius:50%;background:${col};box-shadow:0 0 70px ${col}"></div>`;
