const IMGS={'a man standing in prayer on a mat, reciting (warm light)':'1-prayer','an open mushaf on a wooden stand, morning light':'2-mushaf','men praying Fajr in jamaah in a masjid at dawn, rows from behind':'3-jamaah','a man walking to the masjid at dawn, seen from behind':'4-walking'};
