const TASBIH=(x,y,r=150,fill=33)=>{let s='';for(let i=0;i<33;i++){const a=i/33*2*Math.PI-Math.PI/2;s+=`<circle cx="${r+30+Math.cos(a)*r}" cy="${r+30+Math.sin(a)*r}" r="13" fill="${i<fill?'#1FA34A':'#E6DED2'}" stroke="#151515" stroke-width="3"/>`}return `<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="${2*r+60}" height="${2*r+110}"><circle cx="${r+30}" cy="${r+30}" r="${r}" fill="none" stroke="#8B5E3C" stroke-width="4"/>${s}<path d="M${r+30},${2*r+30} l-16,50 h32 z" fill="#8B5E3C" stroke="#151515" stroke-width="3"/></svg>`};
const STAIRS=(x,y,c='#2F80ED')=>`<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="300" height="200"><path d="M10,190 H80 V140 H150 V90 H220 V40 H290" fill="none" stroke="${c}" stroke-width="14" stroke-linejoin="round"/><path d="M250,20 L290,40 L250,60" fill="none" stroke="${c}" stroke-width="12" stroke-linecap="round"/></svg>`;
const PIE=(x,y,r,parts)=>{let s='';const cols=['#1FA34A','#2F80ED','#E8A92E'];for(let i=0;i<3;i++){const a0=i/3*2*Math.PI-Math.PI/2,a1=(i+1)/3*2*Math.PI-Math.PI/2;const p=(a)=>`${r+10+Math.cos(a)*r},${r+10+Math.sin(a)*r}`;s+=`<path d="M${r+10},${r+10} L${p(a0)} A${r},${r} 0 0 1 ${p(a1)} Z" fill="${i<parts?cols[i]:'#EEE'}" stroke="#151515" stroke-width="6"/>`}return `<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="${2*r+20}" height="${2*r+20}">${s}</svg>`};
const SHIELD=(x,y)=>`<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="150" height="170"><path d="M75,8 L140,30 V85 Q140,140 75,162 Q10,140 10,85 V30 Z" fill="#2F80ED" stroke="#151515" stroke-width="7"/><path d="M45,85 L68,108 L108,62" fill="none" stroke="#fff" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const NIGHT=(x,y,w,f)=>`<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="${w}" height="110"><rect x="4" y="4" width="${w-8}" height="102" rx="20" fill="#1C2340" stroke="#151515" stroke-width="7"/><rect x="11" y="11" width="${(w-22)*f}" height="88" rx="14" fill="#E8A92E"/></svg>`;
const STEPS=(x,y,n)=>{let s='';for(let i=0;i<n;i++){const cx=30+i*120,cy=i%2?40:100;s+=`<ellipse cx="${cx}" cy="${cy}" rx="26" ry="40" fill="#151515" transform="rotate(-70 ${cx} ${cy})"/>`}return `<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="${n*120+40}" height="150">${s}</svg>`};
const CLOCK15=(x,y)=>`<svg class="a" data-k="icon" style="left:${x}px;top:${y}px" width="260" height="260"><circle cx="130" cy="130" r="115" fill="#fff" stroke="#151515" stroke-width="12"/><path d="M130,130 L130,25 A105,105 0 0 1 235,130 Z" fill="rgba(31,163,74,.35)"/><line x1="130" y1="130" x2="130" y2="40" stroke="#151515" stroke-width="10" stroke-linecap="round"/><line x1="130" y1="130" x2="215" y2="130" stroke="#151515" stroke-width="10" stroke-linecap="round"/><circle cx="130" cy="130" r="10" fill="#E31B1B"/></svg>`;
const SCRIPT = "The Prophet, sallallahu alayhi wa sallam, once asked his Companions, is any one of you unable to earn a thousand good deeds every day?\n\nA thousand. Every day. And he wasn't talking about something hard. Just doing seven simple acts can earn you thousands of good deeds every day. And it's not only about the good deeds. Every one of these raises your status with Allah, wipes away your sins, and makes you a better Muslim, one small habit at a time. And all of them come from authentic hadith.\n\nFirst, you need to know how good deeds are counted. The Prophet, sallallahu alayhi wa sallam, said that when you do a good deed, Allah writes it down as ten, and can multiply it up to seven hundred times, and even more. So no good deed is ever just one.\n\nNumber one. SubhanAllah, one hundred times.\n\nThis is the answer the Prophet gave to his own question. He said, glorify Allah one hundred times, and a thousand good deeds will be written for you, or a thousand sins will be wiped away.\n\nOne hundred SubhanAllah takes about two minutes. That's a thousand good deeds in two minutes.\n\nNumber two. Sending salawat on the Prophet.\n\nHe said, whoever sends one salah upon me, Allah sends ten blessings on him, wipes away ten of his sins, and raises him ten levels. In another narration, ten good deeds are written for him.\n\nSo one salawat is ten good deeds. Say it one hundred times, and that's a thousand good deeds, a thousand sins wiped away, and a thousand levels raised. Allahumma salli ala Muhammad. It takes about three minutes.\n\nNumber three. Reading the Quran, letter by letter.\n\nThe Prophet said that every letter you read from the Book of Allah is a good deed, and every good deed is multiplied by ten. Then he said, I'm not saying Alif Lam Mim is one letter. Alif is a letter, Lam is a letter, and Mim is a letter.\n\nSurah al-Fatihah has more than a hundred letters, so every time you recite it, that's more than a thousand good deeds. You recite it at least seventeen times a day in your fard prayers alone. That's more than seventeen thousand good deeds, just from al-Fatihah, every day, without adding anything new.\n\nAnd if you read just one page of the Quran a day, that's thousands more.\n\nNumber four. Surah al-Ikhlas.\n\nThe Prophet, sallallahu alayhi wa sallam, said that Qul huwallahu ahad is equal to a third of the Quran. It's four short ayat, and it takes about ten seconds.\n\nRead it three times, and it's as if you've read the reward of the whole Quran. Thirty seconds a day.\n\nNumber five. One sentence, one hundred times.\n\nThe Prophet said that whoever says, la ilaha illallah, wahdahu la sharika lah, lahul mulku wa lahul hamd, wa huwa ala kulli shayin qadir, one hundred times in a day, gets the reward of freeing ten slaves, one hundred good deeds are written for him, one hundred sins are wiped away, and he's protected from Shaytan for the rest of that day.\n\nNumber six. Fajr and Isha in congregation.\n\nPraying with the jamaah is twenty seven times better than praying alone. But two prayers have something extra. The Prophet said that whoever prays Isha in congregation, it's as if he prayed half the night. And whoever prays Fajr in congregation as well, it's as if he prayed the whole night.\n\nTwo prayers you already have to pray, and you get the reward of standing in prayer all night long.\n\nNumber seven. Walking to the masjid.\n\nThe Prophet said that when you make wudu at home and walk to the masjid to pray, every step you take wipes away a sin, and the next step raises you a level. Every single step.\n\nThe average walk to a masjid is hundreds of steps. So the further you live, the more you earn.\n\nSo let's add up a normal day. One hundred SubhanAllah, a thousand good deeds. One hundred salawat, another thousand. Al-Fatihah in your prayers, more than seventeen thousand. Al-Ikhlas three times, the reward of a whole Quran. One hundred la ilaha illallah. Fajr and Isha with the jamaah, a whole night of prayer. And every step on the way.\n\nThat's close to twenty thousand good deeds a day, before even counting the steps or the night of prayer. And most of it takes less than fifteen minutes, or you're already doing it.\n\nSo, is any one of us unable to earn a thousand good deeds every day?\n\n";
